const raw = String.raw;

export const scopedPatterns = [
  [raw`(?i:a)b`, "Ab"],
  [raw`(?i:a(?-i:b)c)d`, "AbCd"],
  [raw`(?s:a.(?-s:b.)c.)d.`, "a\nbXc\ndX"],
  [raw`(?m:^a$)`, "x\na\ny"],
  [raw`(?m:^$)`, "\r\n"],
  [raw`(?m:^a$)\nB$`, "x\na\nB"],
  [raw`(?-m:^a$)`, "a"],
  [raw`(?ims:^a.$)`, "A\n"],
  [raw`(?im-s:^a.b$)`, "x\nAXB\ny"],
  [raw`(?i-:a)`, "A"],
  [raw`(?i:(a))\1`, "AA"],
  [raw`(?<word>a)(?i:\k<word>)2`, "aA2"],
  [raw`(?<word>k)(?i:\k<word>)`, "kK"],
  [raw`(?<word>ſ)(?i:\k<word>)`, "ſS"],
  [raw`(?i:(a)?())\1`, ""],
  [raw`(?i:(a)){1,3}`, "aAA"],
  [raw`(?i:(?=(?<peek>a))a)`, "A"],
  [raw`(?i:(?<=ab)(?<tail>c))d`, "ABCd"],
  [raw`(?i:\w)`, "K"],
  [raw`(?i:\b(?<word>\w+)\b)`, "ſ"],
  [raw`(?i:\.|\bNULL)`, "Null"],
  [raw`(?i:\P{Lowercase_Letter})`, "!"],
  [raw`(?-i:\P{Lowercase_Letter})`, "A"],
  [raw`(?s:[^].)(?-s:[^].)`, "\n\naX"],
  [raw`(?-i:a)(?i:b)(?-i:c)`, "aBc"],
  [raw`(?s:(?:))(a)`, "a"],
  [raw`(?i:[\q{ab|cd}])`, "AB", "v"],
  [raw`(?-i:[\p{ASCII}--[A-Z]])`, "a", "v"],
  [raw`(?i:[[a-z]&&[^k]])`, "A", "v"],
  [raw`(?i:\p{RGI_Emoji})`, "😀", "v"],
];

